use genewars_runtime::{creature_world::*,blueprint::BlueprintRng};
fn main(){let b=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();assert_eq!(b.len(),261);let before:[u8;124]=b[..124].try_into().unwrap();let expected:[u8;124]=b[124..248].try_into().unwrap();let word=|at|i16::from_le_bytes(b[at..at+2].try_into().unwrap());let rng=BlueprintRng{seed:word(254)as u16,ring:b[256],draw_count:u32::from_le_bytes(b[257..261].try_into().unwrap())};let p=plan_mule_plant_acquisition(&before,word(248),[word(250),word(252)],rng).unwrap();assert_eq!(p.after,expected);assert_eq!(p.rng_after,BlueprintRng{seed:1844,ring:0,draw_count:1184});assert_eq!(p.draws.len(),2);for id in [-1,512,i16::MAX]{assert!(plan_mule_plant_acquisition(&before,id,[word(250),word(252)],rng).is_err());}println!("acquisition124 exactbytes, RNG and3 bounds verified");
if let Some(path)=std::env::args().nth(2){let b=std::fs::read(path).unwrap();assert_eq!(b.len(),256);let before:[u8;124]=b[..124].try_into().unwrap();let expected:[u8;124]=b[124..248].try_into().unwrap();let rng=BlueprintRng{seed:u16::from_le_bytes(b[249..251].try_into().unwrap()),ring:b[251],draw_count:u32::from_le_bytes(b[252..256].try_into().unwrap())};let p=plan_mule_plant_feed(&before,b[248],rng).unwrap();assert_eq!(p.after,expected);assert_eq!(p.rng_after,BlueprintRng{seed:34964,ring:22,draw_count:1270});assert_eq!(p.draws.len(),2);let mut full=before;full[0x66..0x68].copy_from_slice(&2i16.to_le_bytes());assert!(plan_mule_plant_feed(&full,b[248],rng).is_err());println!("feeding124 exactbytes/RNG andenergy-death boundary rejection verified");}}
